class Rectangle {
    protected int width;
    protected int height;

    public void setWidth(int width) { this.width = width; }
    public void setHeight(int height) { this.height = height; }
    public int area() { return width * height; }
}

class Square extends Rectangle {
    @Override
    public void setWidth(int width) {
        this.width = width;
        this.height = width;  // LSP violation: changes both dimensions
    }
    @Override
    public void setHeight(int height) {
        this.width = height;  // LSP violation: breaks caller expectations
        this.height = height;
    }
}

void testArea(Rectangle rect) {
    rect.setWidth(5);
    rect.setHeight(4);
    assert rect.area() == 20;  // Fails if rect is a Square (area = 16)
}

var rectangle = new Rectangle();
testArea(rectangle);  // Works: area = 20

var square = new Square();
testArea(square);  // Breaks: area = 16, assertion fails

interface Shape {
    int area();
    void draw();
}

class Rectangle implements Shape {
    private int width;
    private int height;

    public Rectangle(int width, int height) {
        this.width = width;
        this.height = height;
    }

    public void setWidth(int width) { this.width = width; }
    public void setHeight(int height) { this.height = height; }

    @Override
    public int area() { return width * height; }

    @Override
    public void draw() { System.out.println("Rectangle " + width + "x" + height); }
}

class Square implements Shape {
    private int side;

    public Square(int side) { this.side = side; }  // Single dimension

    public void setSide(int side) { this.side = side; }  // One setter, no confusion

    @Override
    public int area() { return side * side; }

    @Override
    public void draw() { System.out.println("Square " + side + "x" + side); }
}

import java.util.*;

interface PaymentProcessor {
    void processPayment(double amount);
    void refundPayment(String transactionId);
}

class CreditCardProcessor implements PaymentProcessor {
    @Override
    public void processPayment(double amount) {
        System.out.println("Processing credit card payment: $" + amount);
    }

    @Override
    public void refundPayment(String transactionId) {
        System.out.println("Refunding transaction: " + transactionId);
    }
}

class GiftCardProcessor implements PaymentProcessor {
    @Override
    public void processPayment(double amount) {
        System.out.println("Processing gift card payment: $" + amount);
    }

    @Override
    public void refundPayment(String transactionId) {
        throw new UnsupportedOperationException("Gift cards cannot be refunded");  // LSP violation
    }
}

void handleReturn(PaymentProcessor processor, String txnId) {
    processor.refundPayment(txnId);  // Breaks if processor is GiftCardProcessor
}

interface CustomerRepository {
    // Contract: accepts any non-null ID, returns Optional (empty if not found)
    Optional<Customer> findById(Long id);
}

class DatabaseCustomerRepository implements CustomerRepository {
    @Override
    public Optional<Customer> findById(Long id) {
        if (id == null) return Optional.empty();  // Handles null gracefully
        // ... database query
        return Optional.of(new Customer(id, "John Doe"));
    }
}

class CachedCustomerRepository implements CustomerRepository {
    @Override
    public Optional<Customer> findById(Long id) {
        if (id == null || id <= 0) {
            throw new IllegalArgumentException("ID must be positive");  // LSP violation: strengthens precondition
        }
        // ... check cache
        return Optional.empty();
    }
}

void processOrder(CustomerRepository repo, Long customerId) {
    var customer = repo.findById(customerId);  // Breaks if repo is CachedCustomerRepository and customerId is null
    customer.ifPresent(c -> System.out.println("Processing order for " + c.name()));
}
